import fs from 'node:fs';
const dir='research-v2/eurusd-trend-hold-20261012/',r=JSON.parse(fs.readFileSync(dir+'RESULTS.json')),m=JSON.parse(fs.readFileSync(dir+'market.json')),l=JSON.parse(fs.readFileSync(dir+'ledger.json'));
const bars=m.m1.map(c=>({...c,t:Date.parse(c.time)})),now=Date.parse(r.valuedAt),start=Date.parse(r.coverage.startInclusive);
const datedRates=new Map();for(const tx of l.transactions.filter(t=>t.type==='DAILY_FINANCING'))for(const p of tx.positionFinancings||[])if(p.instrument==='EUR_USD')for(const f of p.openTradeFinancings||[]){const rate=+f.financingRate;datedRates.set(tx.time.slice(0,10)+'/'+(rate>0?'short':'long'),rate);}
const rollovers=[];for(let t=Date.UTC(2026,8,28,21);t<=now;t+=86400000){const dow=new Date(t).getUTCDay(),days=[0,1,1,3,1,1,0][dow];if(days)rollovers.push({t,days});}
function finance(x){if(!x.opened_at)return 0;let total=0;for(const d of rollovers){if(Date.parse(x.opened_at)>=d.t||x.exitTime<=d.t)continue;const date=new Date(d.t).toISOString().slice(0,10),rate=datedRates.get(date+'/'+x.direction)??+l.instrument.financing[x.direction==='short'?'shortRate':'longRate'];const mark=bars.findLast(c=>c.t+60000<=d.t);if(mark)total+=x.units*rate/365*d.days*(+mark.mid.c)*(rate>0?.99:1.01);}return total;}
const actualFinanceById=new Map(r.trades.map(t=>[t.id,0]));const source=JSON.parse(fs.readFileSync(dir+'source.json'));source.trades.forEach((t,i)=>actualFinanceById.set(t.id,+m.broker[i]?.financing||0));
const matureIds=new Set(r.trades.filter(t=>Date.parse(t.opened_at)+48*3600000<=now).map(t=>t.id));
for(const key of Object.keys(r.arms))r.arms[key]=r.arms[key].filter(Boolean);
r.costAdjustedSummary={};for(const [name,arm] of Object.entries(r.arms)){for(const x of arm){x.financing=name==='actual'||name==='trendFilterActual'?actualFinanceById.get(x.id):finance(x);x.pnlWithFinancing=x.pnl+x.financing;}const sum=v=>({n:v.length,pnl:v.reduce((a,x)=>a+x.pnl,0),financing:v.reduce((a,x)=>a+x.financing,0),pnlWithFinancing:v.reduce((a,x)=>a+x.pnlWithFinancing,0)});r.costAdjustedSummary[name]={all:sum(arm),mature48h:sum(arm.filter(x=>matureIds.has(x.id)))};}
const first=l.transactions.find(t=>t.accountBalance),startingBalance=+first.accountBalance-(+first.pl||0)-(+first.financing||0);
const holds=r.arms.allShortHoldToday;let minAvailable=Infinity,minAt=null,minOnEntry=Infinity;for(const c of bars.filter(c=>c.t>=start)){const active=holds.filter(x=>Date.parse(x.opened_at)<=c.t),pnl=active.reduce((a,x)=>a+(x.entry-+c.ask.c)*x.units,0),margin=active.reduce((a,x)=>a+x.units,0)*(+c.mid.c)*+l.instrument.marginRate,free=startingBalance+pnl-margin;if(free<minAvailable){minAvailable=free;minAt=c.time;}if(active.some(x=>Date.parse(x.opened_at)>c.t-60000))minOnEntry=Math.min(minOnEntry,free);}
r.holdingExposure.isolatedEURUSDAccount={startingBalanceInferredFromFirstTransaction:startingBalance,minAvailableMarginAtM1Closes:minAvailable,minAvailableMarginTime:minAt,minAvailableMarginNearEntries:minOnEntry,conclusion:'EUR-only replay appears supportable at 2% margin. Actual other-pair exposure and intraminute equity remain unmodeled; this is not proof for the whole account.'};
r.method.costs='Historical bid/ask included. Actual financing verified from broker. Hypothetical financing estimated from observed same-date rates where available, otherwise current instrument rates, with rollover weekday schedule and 1% conversion adjustment. Historical daily rates incomplete. Commission metadata absent; no additional execution slippage modeled.';
r.method.stops=r.method.stops.replace('units reduced','units resized');
fs.writeFileSync(dir+'RESULTS.json',JSON.stringify(r,null,2));
const fmt=x=>Math.round(x).toLocaleString('en-US');const table=Object.entries(r.costAdjustedSummary).map(([name,v])=>`| ${name} | ${v.mature48h.n} | $${fmt(v.mature48h.pnl)} | $${fmt(v.mature48h.financing)} | $${fmt(v.mature48h.pnlWithFinancing)} |`).join('\n');
const md=`# EUR/USD trade replay — October 12, 2026\n\nValued at ${r.valuedAt}. Rolling 14-day window starts ${r.coverage.startInclusive}. 22 broker-verified trades; 17 have a complete 48-hour observation period.\n\n## Completed observations\n\n| Rule | Trades | Price P/L after spread | Financing (actual or estimated) | Combined |\n|---|---:|---:|---:|---:|\n${table}\n\n## Method\n\n${Object.entries(r.method).map(([k,v])=>`- **${k}:** ${v}`).join('\n')}\n\n## Holding everything short until valuation\n\nPrice P/L: $${fmt(r.summary.allShortHoldToday.pnl)}. Estimated financing: $${fmt(r.costAdjustedSummary.allShortHoldToday.all.financing)}. Worst combined M1-close P/L below starting equity: $${fmt(r.holdingExposure.worstCombinedM1ClosePnl)}. Peak-to-trough M1-close equity drawdown: $${fmt(r.holdingExposure.maxDrawdownM1Close)}. Exposure: ${r.holdingExposure.units} EUR. Peak estimated margin: $${fmt(r.holdingExposure.maxMargin)}.\n\n${r.holdingExposure.isolatedEURUSDAccount.conclusion}\n\n## Interpretation\n\nHolding original directions without stops for 48 hours loses; shorting all for 48 hours wins in this sample. Trend-aligned stopped arms lose on completed observations. Keeping original directions but replacing stored stops with the prior 24-hour structural boundary and fixed 2R/48h exits produces a positive exploratory result. This does not isolate stop width from exit changes, and is not out-of-sample evidence. All short entries share the same market move and may overlap. Retaining historical opportunities after altering prior trade outcomes is a conditional replay, not a complete strategy backtest.\n\nNo trade, database, settings, or deployment changes were made.\n`;
fs.writeFileSync(dir+'REPORT.md',md);
console.log(JSON.stringify({costAdjusted:r.costAdjustedSummary,exposure:r.holdingExposure,paired:r.pairedComparison},null,2));
